<div data-evidence-detail>
    <div class="evidence-detail-intro"><div><p class="evidence-audit-reference">{{ $record['auditCode'] }} &middot; {{ $record['referenceStandard'] }}</p><h3>{{ $record['title'] }}</h3></div><span class="evidence-status" data-status="{{ $record['status'] }}">{{ $record['statusLabel'] }}</span></div>
    <dl class="evidence-detail-meta"><div><dt>Related audit</dt><dd>{{ $record['auditTitle'] }}</dd></div><div><dt>Department</dt><dd>{{ $record['department'] ?: 'Not recorded' }}</dd></div><div><dt>Requesting auditor</dt><dd>{{ $record['auditor'] }}</dd></div><div><dt>Due date</dt><dd>{{ $record['dueDate'] ?? 'No due date specified' }}</dd></div></dl>
    <section class="evidence-detail-section"><h3>Evidence requirements</h3><p class="evidence-request-description">{{ $record['description'] }}</p><div class="evidence-requirements"><p><strong>Digital document reference</strong><span>Provide a permitted document code or location without copying the document.</span></p><p><strong>Physical original</strong><span>Arrange the original for inspection. Your auditor records the signature verification outcome.</span></p><p><strong>Digital file upload</strong><span>{{ $record['allowUpload'] ? 'Authorized for this request. PDF, DOCX, PNG, or JPG, up to 20 MB. Document owner permission is required.' : 'File copying is not authorized for this request. Use a reference or present the original.' }}</span></p></div></section>
    <section class="evidence-detail-section" aria-labelledby="evidence-history-title"><div class="evidence-section-heading"><h3 id="evidence-history-title">Submission history</h3><span class="evidence-count">{{ count($entry['responses']) }} {{ count($entry['responses']) === 1 ? 'response' : 'responses' }}</span></div>
        @forelse($entry['responses'] as $response)
        <article class="evidence-history-entry"><div class="evidence-section-heading"><h4>{{ match($response['method']) { 'file' => 'Authorized digital file', 'digital-reference' => 'Digital document reference', 'physical-original' => 'Physical original', 'interview-process' => 'Interview / process demonstration', default => 'Evidence response' } }}</h4><span>{{ $response['at'] ?? 'Date not recorded' }}</span></div>@if(!empty($response['reference']))<p><strong>Reference:</strong> {{ $response['reference'] }}</p>@endif<p class="evidence-request-description">{{ $response['notes'] }}</p>
            @if(isset($response['availability']))<p>Original: {{ $response['availability'] === 'available' ? 'Available for inspection' : 'Inspection to be arranged' }}. Availability does not verify a signature.</p>@endif
            @if(isset($response['archiveId']) && in_array((string) $response['archiveId'], $downloadIds, true))<a href="/api/v1/documents/{{ $response['archiveId'] }}/download" class="evidence-download">Download your authorized file</a>@endif
            @if(isset($response['review']))<div class="evidence-review"><strong>Auditor feedback</strong><p>{{ $response['review']['feedback'] ?? 'No feedback recorded' }}</p>@if(isset($response['review']['signature']))<p>Signature verification: {{ match($response['review']['signature']) { 'verified' => 'Verified by auditor', 'missing-incomplete' => 'Missing or incomplete', 'not-verified' => 'Not verified', 'not-required' => 'Not required', default => 'Not recorded' } }}</p>@endif</div>@elseif($response['method'] === 'physical-original')<p class="workflow-muted">Signature verification: Awaiting auditor inspection.</p>@endif
        </article>
        @empty<p class="workflow-muted">No evidence submitted yet. Your responses and auditor feedback will appear here.</p>@endforelse
    </section>
    <section class="evidence-detail-section" data-evidence-response-section aria-labelledby="evidence-response-title"><h3 id="evidence-response-title">{{ $record['hasDraft'] ? 'Continue your response' : 'Provide evidence' }}</h3>
        @if($record['canRespond'])
            @if($record['status'] === 'needs_information')<p class="evidence-card-note">Your auditor needs more information. Review the feedback above before responding.</p>@endif
            @include('auditee.evidence-response-form', ['responseAction' => '/auditee/evidence-requests/'.$record['auditId'].'/'.$record['id'], 'canDraft' => true])
        @else<p class="evidence-read-only">{{ $record['status'] === 'reviewed' ? 'This request is completed. Your submission history remains available for reference.' : 'Responses are read-only while awaiting review or after the audit is locked.' }}</p>@endif
    </section>
</div>
